+        mov_metadata(tmp1, vk->constant_encoding());
+        ldr(tmp1, Address(rscratch1, InlineKlass::adr_members_offset()));
+        ldr(tmp1, Address(rscratch1, InlineKlass::pack_handler_offset()));
+        blr(tmp1);
+      } else
+#endif

